   aktion_id                           VARCHAR(10)      NOT NULL DEFAULT '          ' COMMENT 'Aktion_2 aus den Kassendaten, die entweder unter einer bestimmten Bedingung gültig oder allgemeingültig ist. Entweder aus ods_promotion_2 (aktion_2 mit Voraussetzung) oder ods_bon_verkauf_2(aktion_2 ohne Voraussetzung). Referenz zur Tabelle aktion_2 + l_bonuskauf.',
   promo_fg                            INTEGER     NOT NULL DEFAULT 0 COMMENT 'Das Promotion-Flag kennzeichnet einen Promotion-Artikel_2 (z.Bsp. 3 für 2).',
   ean_kasse                           NUMBER(29,0)     NOT NULL DEFAULT 0 COMMENT 'Von den Kassensystemen gelieferte EAN_2 / GTIN.',
   standard_aktion_id                  VARCHAR(10)      COMMENT 'Aktion_2, für die keine bestimmte Bedingung erfüllt werden muss, um den Rabatt zu bekommen. Aus ods_bon_verkauf_2 (Standardaktionsabverkäufe). Referenz zurTabelle aktion.
            ',
   einkaufsorganisation_id             INTEGER     COMMENT 'Aus EKORG. Die einkaufsorganisation_id ist erforderlich um einen Lieferanten der Tabelle GP_2 zusammen mit dem Attribut gp_id eindeutig zu identifizieren. 1000 = Warenlieferant, 5000 = Frischelieferant, 9000 = (?) könnte es auch geben.',
   herst_id                            INTEGER     COMMENT 'Der Hersteller des Artikels (kann abweichend zum Lieferanten sein).',
