   bq_findung_id                       INTEGER     COMMENT 'ID zur Kennzeichnung eines Ausstiegspunkts aus dem Kreisprozess.',
   ek_gld                              NUMBER(29,4)     COMMENT 'Gleitender Durchschnittspreis. In KMO die Basis zur Bewertung der Bestände. Hier aus mseg abgeleitet.',
   diff_ek_gld_konz                    NUMBER(29,4)     COMMENT 'Differenz zum gleitenden Durchschnittspreis in Konzernwährung.',
   bonusbasis                          NUMBER(29,4)     COMMENT 'Die Bonusbasis bildet für Artikel_2 mit Luxussteuer die Preisbasis der Reduzierungen nach Abzug der Luxussteuer auf der Ebene EK1N. Quelle: ZEKP.ABONBA.',
   bonusbasis_konz                     NUMBER(29,4)     COMMENT 'Bonusbasis in Konzernwährung, wenn Landeswährung davon abweicht. Die Bonusbasis bildet für Artikel_2 mit Luxussteuer die Preisbasis der Reduzierungen nach Abzug der Luxussteuer auf der Ebene EK1N. Quelle: ZEKP.ABONBA.',
   bewart_det_id                       INTEGER     NOT NULL DEFAULT 9999 COMMENT 'Detaillierte Bewegungsart zum Aufbruch der bestehenden bewart_id.',
